    @inline(__always)
    private func checkRoundedAverageConstantA(_ value: Lane) {
        let mismatches = Mismatches("roundedAverage with a repeating \(hex(value))")
        let bInputs = Inputs.vectors(H.self, seed: 0x9F76_D284_309A_98FA)
        mismatches.check(
            H.repeating(value),
            H(raw: HighwayReference.repeatingU8(value)),
            "repeating"
        )
        for b in bInputs {
            mismatches.check(
                H.roundedAverage(H.repeating(value), b),
                H(raw: HighwayReference.roundedAverageU8(H.repeating(value).raw, b.raw)),
                "b: \(describe(b))"
            )
        }
        mismatches.record()
    }

